function getBudgetPeriod(){var mode=document.getElementById('bVM').value;var year=parseInt(document.getElementById('bY').value,10)||new Date().getFullYear();if(mode==='month'){var month=parseInt(document.getElementById('bM').value,10)||0;return{mode:mode,startYear:year,startMonth:month,endYear:year,endMonth:month,title:MS[month]+' '+year};}if(mode==='range'){var fromYear=parseInt(document.getElementById('bFY').value,10)||year;var fromMonth=parseInt(document.getElementById('bFM').value,10)||0;var toYear=parseInt(document.getElementById('bTY').value,10)||fromYear;var toMonth=parseInt(document.getElementById('bTM').value,10)||fromMonth;var startKey=budgetDateKey(fromYear,fromMonth);var endKey=budgetDateKey(toYear,toMonth);if(startKey>endKey){var tempYear=fromYear,tempMonth=fromMonth;fromYear=toYear;fromMonth=toMonth;toYear=tempYear;toMonth=tempMonth;}return{mode:mode,startYear:fromYear,startMonth:fromMonth,endYear:toYear,endMonth:toMonth,title:'من '+MS[fromMonth]+' '+fromYear+' إلى '+MS[toMonth]+' '+toYear};}return{mode:mode,startYear:year,startMonth:0,endYear:year,endMonth:11,title:'سنة '+year};}
function monthInBudgetPeriod(year,month,period){var key=budgetDateKey(year,month);return key>=budgetDateKey(period.startYear,period.startMonth)&&key<=budgetDateKey(period.endYear,period.endMonth);}
function getBudgetMonths(period){var result=[];for(var year=period.startYear;year<=period.endYear;year++){var startMonth=year===period.startYear?period.startMonth:0;var endMonth=year===period.endYear?period.endMonth:11;for(var month=startMonth;month<=endMonth;month++)result.push({year:year,month:month,label:MS[month]+' '+year});}return result;}
function getBudgetFilteredExpenses(period){return DB.expenses.filter(function(expense){var expenseDate=expense.dt?new Date(expense.dt):null;return expenseDate&&monthInBudgetPeriod(expenseDate.getFullYear(),expenseDate.getMonth(),period);}).sort(function(a,b){return new Date(b.dt)-new Date(a.dt);});}
function getBudgetFilteredReceipts(period){return DB.receipts.filter(function(receipt){var receiptDate=receipt.dt?new Date(receipt.dt):null;return receiptDate&&monthInBudgetPeriod(receiptDate.getFullYear(),receiptDate.getMonth(),period);}).sort(function(a,b){return new Date(b.dt)-new Date(a.dt);});}
function getBudgetSnapshot(period){var months=getBudgetMonths(period);var totalDue=0,totalReceived=0,totalSpent=0,totalOverdue=0;var rows=months.map(function(item){var due=0;var received=0;var overdue=0;var collectors=[];DB.receipts.forEach(function(receipt){var receiptDate=receipt.dt?new Date(receipt.dt):null;if(receiptDate&&receiptDate.getFullYear()===item.year&&receiptDate.getMonth()===item.month){due+=receiptDueTotal(receipt);received+=parseNumber(receipt.t);overdue+=receiptRemainingTotal(receipt);var collector=receiptCollectorName(receipt);if(collector!=='—'&&collectors.indexOf(collector)===-1)collectors.push(collector);}});var spent=0;DB.expenses.forEach(function(expense){var expenseDate=expense.dt?new Date(expense.dt):null;if(expenseDate&&expenseDate.getFullYear()===item.year&&expenseDate.getMonth()===item.month)spent+=parseNumber(expense.am);});var net=received-spent;totalDue+=due;totalReceived+=received;totalSpent+=spent;totalOverdue+=overdue;return{label:item.label,due:due,received:received,collectors:collectors,overdue:overdue,spent:spent,net:net};});return{rows:rows,totalDue:totalDue,totalReceived:totalReceived,totalSpent:totalSpent,totalOverdue:totalOverdue,balance:totalReceived-totalSpent,expenses:getBudgetFilteredExpenses(period),receipts:getBudgetFilteredReceipts(period)};}
function getContractStatus(contract){if(!contract)return'cancelled';if(contract.st==='cancelled')return'cancelled';if(contract.ed){var today=new Date();today.setHours(0,0,0,0);var endDate=new Date(contract.ed);endDate.setHours(0,0,0,0);if(endDate<today)return'expired';}return contract.st||'active';}
function contractActiveInMonth(contract,year,month){if(getContractStatus(contract)==='cancelled')return false;var start=new Date(contract.sd);var end=contract.ed?new Date(contract.ed):null;var point=new Date(year,month,1);if(point<new Date(start.getFullYear(),start.getMonth(),1))return false;if(end&&point>new Date(end.getFullYear(),end.getMonth(),1))return false;return true;}
function activeContractForUnit(unitNumber){var matches=DB.contracts.filter(function(contract){return contract.uN===unitNumber&&getContractStatus(contract)==='active';});matches.sort(function(a,b){return new Date(b.sd)-new Date(a.sd);});return matches[0]||null;}
function findUnitByNumber(unitNumber){var key=normalizeText(unitNumber);if(!key)return null;return DB.units.find(function(unit){return normalizeText(unit&&unit.uN)===key;})||null;}
function buildAutoUnitFromContract(contract,existingUnit){var unit=existingUnit?Object.assign({},existingUnit):{id:Date.now()+Math.floor(Math.random()*1000),nt:''};var currentAddress=normalizeText(unit.ad);unit.uN=normalizeText(contract&&contract.uN);unit.fl=normalizeText(unit.fl)||normalizeText(contract&&contract.fl);unit.uT=(normalizeText(unit.uT)&&normalizeText(unit.uT)!=='شقة'?unit.uT:(contract&&contract.uT)||unit.uT||'شقة');unit.ad=(currentAddress&&currentAddress!=='٢٣ ش عرابي – الأزبكية – القاهرة'?unit.ad:((contract&&contract.ad)||unit.ad||'٢٣ ش عرابي – الأزبكية – القاهرة'));unit.nt=normalizeText(unit.nt);return unit;}
async function ensureUnitForContract(contract){if(!contract||!normalizeText(contract.uN))return null;var existingUnit=findUnitByNumber(contract.uN);var unit=buildAutoUnitFromContract(contract,existingUnit);await dSI('units',unit.id,unit);var unitIndex=DB.units.findIndex(function(item){return item.id===unit.id;});if(unitIndex>-1)DB.units[unitIndex]=unit;else DB.units.push(unit);return unit;}
function cED(){var start=document.getElementById('c9').value;var duration=parseInt(document.getElementById('c7').value,10)||0;if(!start||!duration){syncDateInputMode(document.getElementById('c10'));return;}var endDate=new Date(start);endDate.setMonth(endDate.getMonth()+duration);document.getElementById('c10').value=endDate.toISOString().split('T')[0];syncDateInputMode(document.getElementById('c10'));}
function tI(){document.getElementById('cIF').style.display=document.getElementById('c12').checked?'block':'none';}
function uIL(){document.getElementById('c15').textContent=document.getElementById('c14').value==='fixed'?'القيمة (جنيه)':'النسبة المئوية (%)';}
function hA(input){tmpA=[];var list=document.getElementById('cAL');list.innerHTML='';Array.from(input.files||[]).forEach(function(file){tmpA.push(file.name);list.innerHTML+='<span style="display:inline-block;background:var(--acg);padding:2px 6px;border-radius:5px;margin:2px;font-size:9px;color:var(--ac)">'+h(file.name)+'</span>';});}
function cRF(contract,year,month){var baseRent=Math.round(contractBaseRent(contract));var start=new Date(contract.sd);var target=new Date(year,month,1);var diff=(target.getFullYear()-start.getFullYear())*12+(target.getMonth()-start.getMonth());if(diff<0)return baseRent;if(!contract.ie||!parseNumber(contract.ii))return baseRent;var periods=Math.floor(diff/parseNumber(contract.ii));if(periods<=0)return baseRent;if(contract.iT==='fixed')return Math.round(baseRent+(periods*parseNumber(contract.iv)));return Math.round(baseRent*Math.pow(1+(parseNumber(contract.iv)/100),periods));}
function receiptDueTotal(receipt){if(receipt&&hasValue(receipt.dT))return Math.max(0,parseNumber(receipt.dT));return Math.max(0,parseNumber(receipt&&receipt.bT)+parseNumber(receipt&&receipt.iT)+parseNumber(receipt&&receipt.at));}
function receiptRemainingTotal(receipt){if(receipt&&hasValue(receipt.rm))return Math.max(0,parseNumber(receipt.rm));return Math.max(0,receiptDueTotal(receipt)-parseNumber(receipt&&receipt.t));}
function receiptRentDueTotal(receipt){return Math.max(0,parseNumber(receipt&&receipt.bT)+parseNumber(receipt&&receipt.iT));}
function receiptRentPaidTotal(receipt){var due=receiptRentDueTotal(receipt);var paid=Math.max(0,parseNumber(receipt&&receipt.t));if(!due)return 0;return Math.min(paid,due);}
function receiptSortDateValue(receipt){if(receipt&&receipt.dt){var direct=new Date(receipt.dt);if(!isNaN(direct.getTime()))return direct.getTime();}return receipt&&receipt.ct?new Date(receipt.ct).getTime()||0:0;}
function nextReceiptNumber(){var max=0;DB.receipts.forEach(function(receipt){var match=String(receipt&&receipt.rn||'').match(/^REC-(\d+)$/i);if(!match)return;var value=parseInt(match[1],10);if(!isNaN(value)&&value>max)max=value;});return'REC-'+String(max+1).padStart(4,'0');}
function listContractRentMonths(contract){var startDate=new Date(contract.sd);if(isNaN(startDate.getTime()))return[];var now=new Date();var limit=contract.ed?new Date(contract.ed):now;if(limit>now)limit=now;var cursor=new Date(startDate.getFullYear(),startDate.getMonth(),1);var lastMonth=new Date(limit.getFullYear(),limit.getMonth(),1);var baseRent=Math.round(contractBaseRent(contract));var rows=[];while(cursor<=lastMonth){if(contractActiveInMonth(contract,cursor.getFullYear(),cursor.getMonth())){var fullRent=Math.round(cRF(contract,cursor.getFullYear(),cursor.getMonth()));rows.push({yr:cursor.getFullYear(),mo:cursor.getMonth(),nm:MS[cursor.getMonth()],base:baseRent,full:fullRent,rt:fullRent});}cursor.setMonth(cursor.getMonth()+1);}return rows;}
function applyReceiptRentAllocation(contract,outstandingMap,receipt){if(!receiptMatchesContract(receipt,contract))return;var year=parseInt(latinizeDigits(receipt.yr),10);if(isNaN(year))year=receipt.dt?new Date(receipt.dt).getFullYear():null;if(year==null)return;var months=receiptMonthsArray(receipt).slice().sort(function(a,b){return a-b;});if(!months.length)return;var remaining=receiptRentPaidTotal(receipt);for(var i=0;i<months.length&&remaining>0;i++){var month=months[i];var key=year+'-'+month;if(!Object.prototype.hasOwnProperty.call(outstandingMap,key))continue;var current=Math.max(0,parseNumber(outstandingMap[key]));if(!current)continue;var applied=Math.min(current,remaining);outstandingMap[key]=Math.max(0,current-applied);remaining-=applied;}}
function latestReceiptForContract(contract,receipts){var latest=null;(receipts||[]).forEach(function(receipt){if(!receiptMatchesContract(receipt,contract))return;if(!latest||receiptSortDateValue(receipt)>receiptSortDateValue(latest))latest=receipt;});return latest;}
function latestReceiptMonthForContract(contract,receipts,outstandingMap){var latestReceipt=latestReceiptForContract(contract,receipts);if(!latestReceipt)return null;var year=parseInt(latinizeDigits(latestReceipt.yr),10);if(isNaN(year))year=latestReceipt.dt?new Date(latestReceipt.dt).getFullYear():null;var months=receiptMonthsArray(latestReceipt).slice().sort(function(a,b){return a-b;});if(year!=null&&months.length){if(outstandingMap){for(var i=0;i<months.length;i++){var key=year+'-'+months[i];if(Math.round(Math.max(0,parseNumber(outstandingMap[key]||0)))>0)return new Date(year,months[i],1);}}return new Date(year,months[months.length-1]+1,1);}if(latestReceipt.dt){var receiptDate=new Date(latestReceipt.dt);if(!isNaN(receiptDate.getTime()))return new Date(receiptDate.getFullYear(),receiptDate.getMonth()+1,1);}return null;}
function gUM(contract,receipts,fromDate){var months=listContractRentMonths(contract);var adjustments=contractDemandAdjustments(contract);var excludedSet={};var manualIncludedSet={};adjustments.excluded.forEach(function(key){excludedSet[key]=true;});adjustments.included.forEach(function(key){manualIncludedSet[key]=true;});if(!months.length&&!adjustments.included.length)return[];var outstanding={};var monthMap={};months.forEach(function(item){var key=demandMonthKey(item.yr,item.mo);outstanding[key]=item.full;monthMap[key]=item;});adjustments.included.forEach(function(key){if(excludedSet[key])return;var parsed=parseDemandMonthKey(key);if(!parsed)return;if(!Object.prototype.hasOwnProperty.call(outstanding,key)){var manualRow=demandMonthRowForContract(contract,parsed.yr,parsed.mo,null,true);outstanding[key]=manualRow.full;monthMap[key]=manualRow;return;}monthMap[key]=Object.assign({},monthMap[key],{manual:true});});receipts.filter(function(receipt){return receiptMatchesContract(receipt,contract);}).slice().sort(function(a,b){return receiptSortDateValue(a)-receiptSortDateValue(b);}).forEach(function(receipt){applyReceiptRentAllocation(contract,outstanding,receipt);});Object.keys(manualIncludedSet).forEach(function(key){if(excludedSet[key]||!monthMap[key])return;outstanding[key]=Math.round(monthMap[key].full||0);});var start=demandStartDateForContract(contract,receipts,fromDate,outstanding);var rows=Object.keys(outstanding).filter(function(key){var item=monthMap[key];if(!item||excludedSet[key])return false;var point=new Date(item.yr,item.mo,1);var remaining=Math.round(Math.max(0,outstanding[key]||0));return manualIncludedSet[key]||remaining>0&&(!start||point>=start);}).map(function(key){var item=monthMap[key];var remaining=Math.round(Math.max(0,outstanding[key]||0));return{yr:item.yr,mo:item.mo,nm:item.nm,base:item.base,full:item.full,rt:remaining,manual:item.manual===true||manualIncludedSet[key]===true};});return rows.sort(function(a,b){return a.yr===b.yr?a.mo-b.mo:a.yr-b.yr;});}
function latestPaidMonthForContract(contract,receipts,outstandingMap){return latestReceiptMonthForContract(contract,receipts,outstandingMap);}
function demandStartDateForContract(contract,receipts,fromDate,outstandingMap){var start=fromDate?new Date(fromDate):new Date(contract.sd);if(isNaN(start.getTime()))start=new Date(contract.sd);start=new Date(start.getFullYear(),start.getMonth(),1);var latestReceiptBoundary=latestReceiptMonthForContract(contract,receipts,outstandingMap);if(latestReceiptBoundary&&latestReceiptBoundary>start)start=latestReceiptBoundary;return start;}
function demandMonthRowForContract(contract,year,month,remaining,manual){var fullRent=Math.round(cRF(contract,year,month));var baseRent=Math.round(contractBaseRent(contract));return{yr:year,mo:month,nm:MS[month],base:baseRent,full:fullRent,rt:remaining!=null?Math.round(remaining):fullRent,manual:manual===true};}
function demandEditorYearOptions(contract){var years=[new Date().getFullYear()];if(contract&&contract.sd)years.push(new Date(contract.sd).getFullYear());if(contract&&contract.ed)years.push(new Date(contract.ed).getFullYear());var adjustments=contractDemandAdjustments(contract);adjustments.excluded.concat(adjustments.included).forEach(function(key){var parsed=parseDemandMonthKey(key);if(parsed)years.push(parsed.yr);});years=years.filter(function(year){return isFinite(year);}).sort(function(a,b){return a-b;});if(!years.length)years=[new Date().getFullYear()];var minYear=Math.min.apply(null,years.concat([new Date().getFullYear()-1]));var maxYear=Math.max.apply(null,years.concat([new Date().getFullYear()+1]));var out=[];for(var year=minYear;year<=maxYear;year++)out.push(year);return out;}
async function saveDemandMonthAdjustments(contract,adjustments){if(!contract)return;var nextExcluded=normalizeDemandMonthKeyList(adjustments&&adjustments.excluded||[]);var nextIncluded=normalizeDemandMonthKeyList(adjustments&&adjustments.included||[]).filter(function(key){return nextExcluded.indexOf(key)===-1;});var nextContract=Object.assign({},contract,{dmEx:nextExcluded,dmIn:nextIncluded});await dSI('contracts',nextContract.id,nextContract);var contractIndex=DB.contracts.findIndex(function(item){return sameId(item&&item.id,nextContract.id);});if(contractIndex>-1)DB.contracts[contractIndex]=nextContract;else DB.contracts.push(nextContract);rawCollectionState.contracts=collectionArrayToObject(DB.contracts);if(!io)saveLocalState();else refreshUI();if(!io)syncDBFromRawCollections();refreshUI();demandEditState={contractId:nextContract.id};renderDemandMonthEditor();}
function renderDemandMonthEditorRows(containerId,items,buttonLabel,buttonClass,handlerName,emptyTitle,emptyText){var container=document.getElementById(containerId);if(!container)return;container.innerHTML=items.length?items.map(function(item){return'<div class="ar"><label><span class="primary-cell">'+h(item.label)+'</span><span class="sub-cell">'+h(item.meta||'')+'</span></label><button type="button" class="bt '+buttonClass+' bs" onclick=\''+handlerName+'('+jsArg(item.key)+')\'>'+buttonLabel+'</button></div>';}).join(''):emptyState(emptyTitle,emptyText,'fas fa-calendar');}
function fillDemandMonthEditorSelect(select,options,currentValue){if(!select)return;select.innerHTML=options.map(function(option){return'<option value="'+option.value+'">'+option.label+'</option>';}).join('');if(currentValue!==''&&options.some(function(option){return String(option.value)===String(currentValue);})){select.value=String(currentValue);return;}if(options.length)select.value=String(options[options.length-1].value);}
function resetDemandMonthEditorPanels(){['dMMCurrent','dMMExcluded','dMMIncluded'].forEach(function(id){var el=document.getElementById(id);if(el)el.innerHTML='';});}
function closeDemandMonthEditor(){demandEditState=null;resetDemandMonthEditorPanels();hideEl('dMMHost');}
function renderDemandMonthEditorButton(contractId){return'<button type="button" class="bt bt0 bs demand-month-editor-btn" data-contract-id="'+h(contractId==null?'':String(contractId))+'"><i class="fas fa-pen"></i>إدارة الشهور</button>';}
function bindDemandMonthEditorButtons(){Array.from(document.querySelectorAll('.demand-month-editor-btn')).forEach(function(button){button.onclick=function(event){event.preventDefault();event.stopPropagation();openDemandMonthEditor(button.getAttribute('data-contract-id'));};});}
function showDemandMonthEditorPanel(){var host=document.getElementById('dMMHost');if(!host)return false;showEl('dMMHost','block');if(typeof host.scrollIntoView==='function'){try{host.scrollIntoView({behavior:'smooth',block:'start'});}catch(error){host.scrollIntoView();}}return true;}
function renderDemandMonthEditor(){if(!demandEditState)return false;var contract=findContractById(demandEditState.contractId);if(!contract){closeDemandMonthEditor();to('العقد غير موجود','error');return false;}demandEditState.contractId=contract.id;var years=demandEditorYearOptions(contract);var yearSelect=document.getElementById('dMMY');var monthSelect=document.getElementById('dMMM');if(!yearSelect||!monthSelect){to('تعذر فتح صفحة إدارة الشهور','error');return false;}var currentYearValue=yearSelect.value;var currentMonthValue=monthSelect.value;fillDemandMonthEditorSelect(yearSelect,years.map(function(year){return{value:year,label:year};}),currentYearValue);fillDemandMonthEditorSelect(monthSelect,MS.map(function(name,index){return{value:index,label:name};}),currentMonthValue);document.getElementById('dMMN').textContent=contract.tN||'—';document.getElementById('dMMU').textContent='وحدة '+(contract.uN||'—')+' / الدور '+(contract.fl||'—');var hint=document.getElementById('dMMHint');if(hint)hint.textContent='أدر شهور المطالبة الخاصة بالمستأجر الحالي مباشرة من هذه اللوحة.';var adjustments=contractDemandAdjustments(contract);var currentMonths=[];try{currentMonths=gUM(contract,DB.receipts,currentDemandFromDate()).map(function(item){var key=demandMonthKey(item.yr,item.mo);return{key:key,label:item.nm+' '+item.yr,meta:'القيمة الحالية '+moneyLabel(item.rt)+(item.manual?' / مضاف يدويًا':'')};});}catch(error){console.error(error);to('تعذر تحميل بعض شهور المطالبة الحالية، لكن يمكن متابعة التعديل يدويًا','error');}var excludedMonths=adjustments.excluded.map(function(key){return{key:key,label:demandMonthLabelFromKey(key),meta:'لن يظهر هذا الشهر داخل المطالبات حتى تتم إعادته'};});var includedMonths=adjustments.included.map(function(key){return{key:key,label:demandMonthLabelFromKey(key),meta:'مضاف يدويًا إلى المطالبة'};});renderDemandMonthEditorRows('dMMCurrent',currentMonths,'إزالة','bt3','removeDemandMonthFromEditor','لا توجد شهور مطلوبة حالياً','كل الشهور الحالية مسددة أو غير داخلة في المطالبة.');renderDemandMonthEditorRows('dMMExcluded',excludedMonths,'إرجاع','bt0','restoreDemandMonthFromEditor','لا توجد شهور مستبعدة','أي شهر تستبعديه من المطالبة سيظهر هنا.');renderDemandMonthEditorRows('dMMIncluded',includedMonths,'حذف الإضافة','bt2','removeManualDemandMonthFromEditor','لا توجد شهور مضافة','يمكنك إضافة شهر يدويًا من الأعلى عند الحاجة.');return true;}
function openDemandMonthEditor(contractId){if(!requirePermission('contractsManage','ليس لديك صلاحية تعديل المطالبات'))return;var contract=findContractById(contractId);if(!contract){to('العقد غير موجود أو المعرّف غير صحيح','error');return;}var yearSelect=document.getElementById('dMMY');var monthSelect=document.getElementById('dMMM');demandEditState={contractId:contract.id};if(yearSelect)yearSelect.innerHTML='';if(monthSelect)monthSelect.innerHTML='';resetDemandMonthEditorPanels();if(!showDemandMonthEditorPanel()){to('تعذر فتح صفحة إدارة الشهور','error');return;}if(!renderDemandMonthEditor())return;}
async function addDemandMonthFromEditor(){if(!demandEditState)return;var contract=findContractById(demandEditState.contractId);if(!contract){to('العقد غير موجود','error');return;}var key=demandMonthKey(document.getElementById('dMMY').value,document.getElementById('dMMM').value);if(!key){to('اختاري شهرًا صحيحًا','error');return;}var adjustments=contractDemandAdjustments(contract);if(adjustments.excluded.indexOf(key)!==-1)adjustments.excluded=adjustments.excluded.filter(function(item){return item!==key;});if(adjustments.included.indexOf(key)===-1)adjustments.included.push(key);await saveDemandMonthAdjustments(contract,adjustments);to('تمت إضافة الشهر إلى المطالبة');}
async function removeDemandMonthFromEditor(key){if(!demandEditState)return;var contract=findContractById(demandEditState.contractId);if(!contract){to('العقد غير موجود','error');return;}var adjustments=contractDemandAdjustments(contract);var existsAutomatically=listContractRentMonths(contract).some(function(item){return demandMonthKey(item.yr,item.mo)===key;});if(adjustments.included.indexOf(key)!==-1)adjustments.included=adjustments.included.filter(function(item){return item!==key;});if(existsAutomatically&&adjustments.excluded.indexOf(key)===-1)adjustments.excluded.push(key);await saveDemandMonthAdjustments(contract,adjustments);to('تمت إزالة الشهر من المطالبة');}
async function restoreDemandMonthFromEditor(key){if(!demandEditState)return;var contract=findContractById(demandEditState.contractId);if(!contract){to('العقد غير موجود','error');return;}var adjustments=contractDemandAdjustments(contract);adjustments.excluded=adjustments.excluded.filter(function(item){return item!==key;});await saveDemandMonthAdjustments(contract,adjustments);to('تمت إعادة الشهر إلى المطالبة');}
async function removeManualDemandMonthFromEditor(key){if(!demandEditState)return;var contract=findContractById(demandEditState.contractId);if(!contract){to('العقد غير موجود','error');return;}var adjustments=contractDemandAdjustments(contract);adjustments.included=adjustments.included.filter(function(item){return item!==key;});await saveDemandMonthAdjustments(contract,adjustments);to('تم حذف الشهر المضاف يدويًا');}
function syncDBFromRawCollections(){var normalized=normalizeBackupData(rawCollectionState);if(!normalized){DB.contracts=[];DB.units=[];DB.receipts=[];DB.expenses=[];return;}DB.contracts=normalized.contracts||[];DB.units=normalized.units||[];DB.receipts=normalized.receipts||[];DB.expenses=normalized.expenses||[];}
