function exRn(){if(!requirePermission('exports','ليس لديك صلاحية التصدير'))return;var now=new Date();downloadXLSX(DB.contracts.filter(function(contract){return getContractStatus(contract)==='active';}).map(function(contract,index){var original=contractBaseRent(contract);var current=Math.round(cRF(contract,now.getFullYear(),now.getMonth()));return{'#':index+1,'المستأجر':contract.tN,'رقم الوحدة':contract.uN,'الدور':contract.fl,'الإيجار الأصلي':original,'الزيادة':Math.max(0,current-original),'الإيجار الحالي':current,'البداية':contract.sd,'النهاية':contract.ed};}),'الإيجارات');}
function buildDemands(){var demandDateInput=document.getElementById('dFD');var fromDate=demandDateInput&&demandDateInput.value?demandDateInput.value:getDefaultDemandFilterDate();return DB.contracts.filter(function(contract){return getContractStatus(contract)==='active'||getContractStatus(contract)==='expired';}).sort(compareContractsByFloor).map(function(contract){var unpaid=gUM(contract,DB.receipts,fromDate);if(!unpaid.length)return null;var total=unpaid.reduce(function(sum,item){return sum+item.rt;},0);return{id:contract.id,tN:contract.tN,uN:contract.uN,fl:contract.fl,ph:contract.ph,cnt:unpaid.length,ms:unpaid.map(function(item){return item.nm+' '+item.yr;}).join(' ، '),bk:unpaid.map(function(item){return item.nm+' '+item.yr+': '+money(item.rt);}).join(' | '),tl:total};}).filter(Boolean);}
function openReceiptForContract(contractId){if(!requirePermission('receiptsManage','ليس لديك صلاحية إدارة الإيصالات'))return;var contract=findContractById(contractId);if(!contract){to('العقد غير موجود','error');return;}oRM();selRC(contract.id);}
function renderDemandActions(item,index,canEdit,canReceipt){var buttons=[];if(canEdit)buttons.push(renderDemandMonthEditorButton(item.id));if(canReceipt)buttons.push('<button type="button" class="bt bt1 bs" onclick=\'openReceiptForContract('+jsArg(item.id)+')\'><i class="fas fa-receipt"></i>إيصال</button>');buttons.push('<button type="button" class="bt bt2 bs" onclick="sWByIndex('+index+')"><i class="fab fa-whatsapp"></i>واتساب</button>');return'<div class="actions">'+buttons.join('')+'</div>';}
function rDM(filterText){var demandDateInput=document.getElementById('dFD');if(demandDateInput&&!demandDateInput.value){demandDateInput.value=getDefaultDemandFilterDate();syncDateInputMode(demandDateInput);}if(demandDateInput)setDemandFilterDate(demandDateInput.value||getDefaultDemandFilterDate());if(filterText!=null)searchState.demands=filterText;var canReceipt=hasPermission('receiptsManage');var canEdit=hasPermission('contractsManage');var query=((searchState.demands!=null?searchState.demands:(document.getElementById('dQ')&&document.getElementById('dQ').value)||'')+'').toLowerCase();syncSearchInput('dQ',searchState.demands||'');var allDemands=buildDemands().filter(function(item){return!query||String(item.tN||'').toLowerCase().includes(query)||String(item.uN||'').toLowerCase().includes(query)||String(item.ms||'').toLowerCase().includes(query)||String(item.bk||'').toLowerCase().includes(query);});document.getElementById('dMF').innerHTML=renderFilterChips('demands',[{value:'all',label:'الكل'},{value:'withPhone',label:'بها هاتف'},{value:'over5000',label:'فوق 5000'},{value:'long',label:'3 شهور فأكثر'}]);window._dm=allDemands.filter(function(item){return quickFilters.demands==='all'||(quickFilters.demands==='withPhone'&&normalizeText(item.ph))||(quickFilters.demands==='over5000'&&item.tl>=5000)||(quickFilters.demands==='long'&&item.cnt>=3);});var demandTotal=window._dm.reduce(function(sum,item){return sum+item.tl;},0);var biggest=window._dm.reduce(function(max,item){return Math.max(max,item.tl||0);},0);var withPhones=window._dm.filter(function(item){return normalizeText(item.ph);}).length;document.getElementById('dMS').innerHTML=summaryCard('مطالبات مفتوحة',String(window._dm.length),'عدد الحالات المعروضة الآن','rd')+summaryCard('إجمالي المتأخرات',moneyLabel(demandTotal),'مجموع كل المطالبات الحالية','gn')+summaryCard('أكبر مطالبة',moneyLabel(biggest),'أعلى قيمة متأخرة حالياً','gd')+summaryCard('جاهزة للتواصل',String(withPhones),'مطالبات لها رقم هاتف محفوظ','bl');document.getElementById('dT').innerHTML=window._dm.length?window._dm.map(function(item,index){var actions=renderDemandActions(item,index,canEdit,canReceipt);return'<tr class="fi"><td><span class="primary-cell">'+h(item.tN)+'</span><span class="sub-cell">'+h(item.ph||'بدون هاتف محفوظ')+'</span></td><td>'+h(item.uN)+'</td><td><span class="bg2">'+item.cnt+' شهر</span></td><td style="font-size:9px;max-width:160px;overflow:hidden;text-overflow:ellipsis">'+h(item.ms)+'</td><td style="font-size:9px;max-width:200px;overflow:hidden;text-overflow:ellipsis">'+h(item.bk)+'</td><td style="font-weight:700;color:var(--dn)">'+moneyLabel(item.tl)+'</td><td>'+actions+'</td></tr>';}).join(''):emptyState('لا توجد مطالبات حالياً','كل العقود مسددة أو لا توجد نتائج مطابقة للبحث الحالي.','fas fa-bell-slash',7);document.getElementById('dMMC').innerHTML=window._dm.length?window._dm.map(function(item,index){var actions=renderDemandActions(item,index,canEdit,canReceipt);return mobileCard(h(item.tN),h(item.ph||'بدون هاتف محفوظ'),'<span class="tag danger">'+moneyLabel(item.tl)+'</span>',[mobileRow('الوحدة',h(item.uN)),mobileRow('عدد الشهور',h(item.cnt+' شهر')),mobileRow('الأشهر',h(item.ms)),mobileRow('التفصيل',h(item.bk))],actions);}).join(''):emptyState('لا توجد مطالبات حالياً','كل العقود مسددة أو لا توجد نتائج مطابقة للبحث الحالي.','fas fa-bell-slash');bindDemandMonthEditorButtons();}
function sWByIndex(index){var item=window._dm[index];if(!item||!item.ph){to('لا يوجد رقم هاتف محفوظ','error');return;}var url=buildWhatsAppUrl(item.ph,'عزيزي/عزيزتي '+item.tN+'\n\nمستحقات إيجار متأخرة عن وحدة '+item.uN+'\n\nعدد الشهور: '+item.cnt+'\nالأشهر: '+item.ms+'\nالإجمالي: '+money(item.tl)+' جنيه\n\nأملاك بن زقر');if(!url){to('رقم واتساب غير صالح','error');return;}window.open(url,'_blank');}
function receiptWhatsAppMessage(receipt){return'إيصال سداد من أملاك بن زقر\n\nالمستأجر: '+(receipt.tN||'—')+'\nرقم الإيصال: '+(receipt.rn||'—')+'\nالوحدة: '+(receipt.uN||'—')+'\nعن أشهر: '+receiptMonthsLabel(receipt)+'\nالإجمالي المستحق: '+money(receiptDueTotal(receipt))+' جنيه\nالمدفوع: '+money(parseNumber(receipt.t))+' جنيه\nالمتبقي: '+money(receiptRemainingTotal(receipt))+' جنيه\nالتاريخ: '+(receipt.dt||'—')+'\n\nأملاك بن زقر';}
function shareReceiptOnWhatsApp(id){var receipt=DB.receipts.find(function(item){return item.id===id;});if(!receipt){to('الإيصال غير موجود','error');return;}var phone=extractPhoneValue(receipt);if(!phone){var contract=DB.contracts.find(function(item){return receiptMatchesContract(receipt,item);});phone=extractPhoneValue(contract);}if(!phone){to('لا يوجد رقم واتساب محفوظ لهذا الإيصال','error');return;}var url=buildWhatsAppUrl(phone,receiptWhatsAppMessage(receipt));if(!url){to('رقم واتساب غير صالح','error');return;}window.open(url,'_blank');}
function exD(){if(!requirePermission('exports','ليس لديك صلاحية التصدير'))return;downloadXLSX((window._dm||[]).map(function(item){return{'المستأجر':item.tN,'رقم الوحدة':item.uN,'عدد الشهور':item.cnt,'الأشهر':item.ms,'التفصيل':item.bk,'الإجمالي':item.tl};}),'المطالبات');}
function resetReceiptExtras(){EXTRA_FIELDS.forEach(function(field){document.getElementById(field.inputId).value='0';});document.getElementById('rAT').textContent='0 جنيه';document.getElementById('rGT').textContent='0 جنيه';document.getElementById('rDT').value='0 جنيه';document.getElementById('rRT').value='0 جنيه';}
function syncReceiptCollectorInput(){var mode=document.getElementById('rRB').value;var wrap=document.getElementById('rRBW');wrap.style.display=mode==='manual'?'block':'none';if(mode!=='manual')document.getElementById('rRBM').value='';updateReceiptPreview();}
function toggleReceiptNotes(){var enabled=!!document.getElementById('rNE').checked;var wrap=document.getElementById('rNW');if(wrap)wrap.style.display=enabled?'block':'none';if(!enabled)document.getElementById('rNT').value='';}
function receiptCollectorName(receipt){return normalizeText(receipt&&receipt.rb)||'—';}
function getReceiptCollectorValue(){var mode=document.getElementById('rRB').value;if(mode==='manual'){var manual=normalizeText(document.getElementById('rRBM').value);return manual||'—';}return mode||'—';}
function currentEditingReceipt(){var input=document.getElementById('rEI');if(!input||!input.value)return null;var id=parseInt(input.value,10);if(isNaN(id))return null;return DB.receipts.find(function(item){return item.id===id;})||null;}
function currentDemandFromDate(){var input=document.getElementById('dFD');return input&&input.value?input.value:getDefaultDemandFilterDate();}
function getReceiptSelectedInputs(){return Array.from(document.querySelectorAll('#rMs input[type=checkbox]:checked'));}
function getReceiptSelectedMonthCount(){return getReceiptSelectedInputs().length;}
function getReceiptMonthlyExtrasFromReceipt(receipt){if(receipt&&receipt.exm&&typeof receipt.exm==='object'&&Object.keys(receipt.exm).length)return receipt.exm;var totals=getReceiptExtras(receipt);var monthCount=(receipt&&receipt.ms&&receipt.ms.length)||1;var extras={};EXTRA_FIELDS.forEach(function(field){var total=parseNumber(totals[field.key]);extras[field.key]=monthCount>1?Math.round((total/monthCount)*100)/100:total;});return extras;}
function toggleReceiptPaymentMode(){var partial=document.getElementById('rPM').value==='partial';document.getElementById('rPAW').style.display=partial?'block':'none';updateReceiptPaymentFields();}
function updateReceiptPaymentFields(){var due=Math.max(0,parseNumber(document.getElementById('rGT').textContent));var partial=document.getElementById('rPM').value==='partial';var paid=partial?parseNumber(document.getElementById('rPA').value):due;if(!partial)document.getElementById('rPA').value=due;paid=Math.max(0,paid);if(due>0&&paid>due){paid=due;document.getElementById('rPA').value=paid;}document.getElementById('rDT').value=moneyLabel(due);document.getElementById('rRT').value=moneyLabel(Math.max(0,due-paid));updateReceiptPreview();}
function updateReceiptPreview(){var tenant=document.getElementById('rTN');var unit=document.getElementById('rUN');var dateInput=document.getElementById('rDt');var dueInput=document.getElementById('rDT');var paidInput=document.getElementById('rPA');var remainingInput=document.getElementById('rRT');var monthsWrap=document.getElementById('rPVM');var note=document.getElementById('rPVDM');if(!tenant||!unit||!dateInput||!dueInput||!monthsWrap||!note)return;document.getElementById('rPVN').textContent=tenant.textContent||'—';document.getElementById('rPVU').textContent=unit.value||'—';document.getElementById('rPVRB').textContent=getReceiptCollectorValue();document.getElementById('rPVD').textContent=dateInput.value?fD2(dateInput.value):'—';document.getElementById('rPVDT').textContent=dueInput.value||'0 جنيه';document.getElementById('rPVT').textContent=moneyLabel(parseNumber(paidInput.value||0));document.getElementById('rPVRT').textContent=remainingInput.value||'0 جنيه';var selectedMonths=getReceiptSelectedInputs().map(function(input){return input.nextElementSibling?input.nextElementSibling.textContent:'';}).filter(Boolean);document.getElementById('rPVC').textContent=String(selectedMonths.length);monthsWrap.innerHTML=selectedMonths.length?selectedMonths.map(function(label){return'<span>'+h(label)+'</span>';}).join(''):'<span>لا توجد أشهر محددة</span>';var demandText=(document.getElementById('rLD').textContent||'').trim();note.textContent=demandText||'اختر المستأجر أولاً لمعرفة الملخص السريع للمطالبة والإيصال.';}
function populateReceiptYears(contract){var select=document.getElementById('rY');select.innerHTML='';var currentYear=new Date().getFullYear();var startYear=contract&&contract.sd?new Date(contract.sd).getFullYear():currentYear-2;var demandStartYear=contract?demandStartDateForContract(contract,DB.receipts,currentDemandFromDate()).getFullYear():currentYear;if(isFinite(demandStartYear))startYear=Math.min(startYear,demandStartYear);var endYear=contract&&contract.ed?new Date(contract.ed).getFullYear():currentYear+1;if(!isFinite(startYear))startYear=currentYear-2;if(!isFinite(endYear))endYear=currentYear+1;startYear=Math.min(startYear,currentYear-2);endYear=Math.max(endYear,currentYear+1);for(var year=startYear;year<=endYear;year++){var option=document.createElement('option');option.value=year;option.textContent=year;select.appendChild(option);}select.value=isFinite(demandStartYear)?demandStartYear:currentYear;}
function oRM(){if(!requirePermission('receiptsManage','ليس لديك صلاحية إدارة الإيصالات'))return;sRC=null;document.getElementById('rMT').textContent='إيصال جديد';document.getElementById('rSB').innerHTML='<i class="fas fa-save"></i>حفظ';document.getElementById('rS').value='';document.getElementById('rTN').textContent='—';['rUN','rUT','rAD','rCI','rEI'].forEach(function(id){document.getElementById(id).value='';});document.getElementById('rRB').value='أ/ محمد عبد العظيم';document.getElementById('rRBM').value='';document.getElementById('rPM').value='full';document.getElementById('rPA').value='0';document.getElementById('rNE').checked=false;document.getElementById('rNT').value='';syncReceiptCollectorInput();document.getElementById('rB').value='0 جنيه';document.getElementById('rBT').value='0 جنيه';document.getElementById('rIT').value='0 جنيه';document.getElementById('rMC').value='٠';document.getElementById('rRV').value='0 جنيه';document.getElementById('rLD').textContent='اختر المستأجر أولاً.';document.getElementById('rD').classList.remove('sh');resetReceiptExtras();populateReceiptYears(null);document.getElementById('rDt').value=todayIso();document.getElementById('rMs').innerHTML='';syncAllDateInputs();toggleReceiptNotes();toggleReceiptPaymentMode();updateReceiptPreview();oM('rM');}
function srT(value){var dropdown=document.getElementById('rD');if(!value.trim()){dropdown.classList.remove('sh');dropdown.innerHTML='';return;}var query=value.toLowerCase();var results=DB.contracts.filter(function(contract){return getContractStatus(contract)==='active'&&(String(contract.tN||'').toLowerCase().includes(query)||String(contract.uN||'').toLowerCase().includes(query));}).sort(compareContractsByFloor).slice(0,8);dropdown.innerHTML=results.map(function(contract){return'<a onclick="selRC('+contract.id+')">'+h(contract.tN)+' — وحدة '+h(contract.uN)+'</a>';}).join('');dropdown.classList.toggle('sh',results.length>0);}
function updateReceiptMonths(){if(!sRC)return;var editingReceipt=currentEditingReceipt();var receiptPool=editingReceipt?DB.receipts.filter(function(item){return item.id!==editingReceipt.id;}):DB.receipts;var fromDate=currentDemandFromDate();var allUnpaid=gUM(sRC,receiptPool,fromDate);var editYear=editingReceipt?parseInt(latinizeDigits(editingReceipt.yr),10):null;var editMonths=editingReceipt?receiptMonthsArray(editingReceipt):[];var allVisible=allUnpaid.slice();if(editingReceipt&&editMonths.length&&isFinite(editYear)){editMonths.forEach(function(month){var exists=allVisible.some(function(item){return item.yr===editYear&&item.mo===month;});if(!exists){var full=Math.round(cRF(sRC,editYear,month));allVisible.push({yr:editYear,mo:month,nm:MS[month],base:Math.round(contractBaseRent(sRC)),full:full,rt:full});}});allVisible.sort(function(a,b){return a.yr===b.yr?a.mo-b.mo:a.yr-b.yr;});}var select=document.getElementById('rY');var year=parseInt(select.value,10);var unpaid=allVisible.filter(function(item){return item.yr===year;});if(!unpaid.length&&allVisible.length){select.value=allVisible[0].yr;year=parseInt(select.value,10);unpaid=allVisible.filter(function(item){return item.yr===year;});}document.getElementById('rMs').innerHTML=unpaid.length?unpaid.map(function(item){var checked=editingReceipt&&item.yr===editYear&&editMonths.indexOf(item.mo)!==-1?' checked':'';return'<label><input type="checkbox" value="'+item.mo+'" data-amount="'+item.rt+'" data-full="'+item.full+'" data-base="'+(item.base||0)+'"'+checked+' onchange="cRM()"><span>'+item.nm+'</span></label>';}).join(''):'<span style="color:var(--tx3);font-size:10px">لا توجد مطالبات لهذه السنة</span>';document.getElementById('rLD').innerHTML=allVisible.length?'<div style="display:flex;flex-wrap:wrap;gap:3px">'+allVisible.map(function(item){return'<span class="bg2">'+item.nm+' '+item.yr+': '+money(item.rt)+'</span>';}).join('')+'</div>':'<span style="color:var(--ac)">لا توجد مطالبات مفتوحة</span>';cRM();}
function selRC(id){var contract=DB.contracts.find(function(item){return item.id===id;});if(!contract)return;sRC=contract;populateReceiptYears(contract);document.getElementById('rD').classList.remove('sh');document.getElementById('rS').value=contract.tN+' — وحدة '+contract.uN;document.getElementById('rTN').textContent=contract.tN;document.getElementById('rUN').value=contract.uN;document.getElementById('rUT').value=contract.uT;document.getElementById('rAD').value=contract.ad;document.getElementById('rCI').value=contract.id;document.getElementById('rB').value=money(cRF(contract,parseInt(document.getElementById('rY').value,10),new Date().getMonth()))+' جنيه';updateReceiptMonths();}
function cRM(){if(!sRC)return;var checked=getReceiptSelectedInputs();var baseTotal=0;var increaseTotal=0;var remainingRentTotal=0;checked.forEach(function(input){var monthDue=Math.max(0,parseNumber(input.dataset.amount));var fullRent=Math.max(1,parseNumber(input.dataset.full)||monthDue||1);var baseRent=Math.max(0,parseNumber(input.dataset.base));var ratio=Math.min(1,monthDue/fullRent);var proportionalBase=Math.round(baseRent*ratio);var proportionalIncrease=Math.max(0,Math.round(monthDue-proportionalBase));baseTotal+=proportionalBase;increaseTotal+=proportionalIncrease;remainingRentTotal+=monthDue;});document.getElementById('rBT').value=moneyLabel(baseTotal);document.getElementById('rIT').value=moneyLabel(increaseTotal);document.getElementById('rMC').value=checked.length||'٠';document.getElementById('rRV').value=moneyLabel(remainingRentTotal);document.getElementById('rB').value=checked.length?moneyLabel(Math.round(remainingRentTotal/checked.length)):'0 جنيه';cRT();}
